'use client';

import { useState, useEffect, ReactNode } from 'react';
import {
  Maximize2,
  Minimize2,
  X,
  Menu,
  ChevronLeft,
  ChevronRight,
  Home,
  User,
  Settings,
  Layers,
  Bell,
  Pin,
  PlusCircle,
} from 'lucide-react';
import type { Tenant } from '@prisma/client'; // Ensure this path is correct

// Define the Notification type
interface Notification {
  id: number;
  text: string;
  read: boolean;
}

interface DashboardLayoutClientProps {
  tenant: Tenant;
  initialDashboardContent: ReactNode;
}

export default function DashboardLayoutClient({ tenant, initialDashboardContent }: DashboardLayoutClientProps) {
  const [sidebarExpanded, setSidebarExpanded] = useState(true);
  const [activeSection, setActiveSection] = useState('Overview');

  const [minimizedCards, setMinimizedCards] = useState<number[]>(() => {
    if (typeof window !== 'undefined') {
      const stored = localStorage.getItem(`minimizedCards_client_${tenant.id}`);
      try {
        return stored ? JSON.parse(stored) : [];
      } catch (e) { console.error("Error parsing minimizedCards_client from localStorage", e); return []; }
    }
    return [];
  });

  const [maximizedCard, setMaximizedCard] = useState<number | null>(null);
  const [showModal, setShowModal] = useState(false);

  const [pinnedCards, setPinnedCards] = useState<number[]>(() => {
    if (typeof window !== 'undefined') {
      const stored = localStorage.getItem(`pinnedCards_client_${tenant.id}`);
      try {
        return stored ? JSON.parse(stored) : [];
      } catch (e) { console.error("Error parsing pinnedCards_client from localStorage", e); return []; }
    }
    return [];
  });

  const [notifications, setNotifications] = useState<Notification[]>(() => {
    const initialNotifications: Notification[] = [
      { id: 1, text: `Welcome to ${tenant.name}'s client dashboard!`, read: false },
      { id: 2, text: "System update scheduled for tonight.", read: false },
      { id: 3, text: "Your monthly report is ready.", read: true },
    ];
    if (typeof window !== 'undefined') {
      const stored = localStorage.getItem(`notifications_client_${tenant.id}`);
      try {
        return stored ? JSON.parse(stored) : initialNotifications;
      } catch (e) {
        console.error("Error parsing notifications_client from localStorage", e);
        return initialNotifications;
      }
    }
    return initialNotifications;
  });
  const [showNotifications, setShowNotifications] = useState(false);

  useEffect(() => {
    if (typeof window !== 'undefined') {
      localStorage.setItem(`minimizedCards_client_${tenant.id}`, JSON.stringify(minimizedCards));
    }
  }, [minimizedCards, tenant.id]);

  useEffect(() => {
    if (typeof window !== 'undefined') {
      localStorage.setItem(`pinnedCards_client_${tenant.id}`, JSON.stringify(pinnedCards));
    }
  }, [pinnedCards, tenant.id]);

  useEffect(() => {
    if (typeof window !== 'undefined') {
      localStorage.setItem(`notifications_client_${tenant.id}`, JSON.stringify(notifications));
    }
  }, [notifications, tenant.id]);

  const mainBoardCards = [
    { id: 1, title: 'Global Analytics', themeColorVar: '--chart-1' }, // Using CSS var name for theme
    { id: 2, title: 'Team Tasks', themeColorVar: '--chart-2' },
    { id: 3, title: 'Financial Reports', themeColorVar: '--chart-3' },
    { id: 4, title: 'User Management', themeColorVar: '--chart-4' },
  ];

  const navItems = [
    { icon: <Home size={20} />, title: 'Overview' },
    { icon: <Layers size={20} />, title: 'Main Board' },
    { icon: <User size={20} />, title: 'My Account' },
    { icon: <Settings size={20} />, title: 'Settings' },
  ];

  const toggleSidebar = () => setSidebarExpanded(!sidebarExpanded);

  const toggleMinimizeCard = (cardId: number) => {
    setMinimizedCards(prev => prev.includes(cardId) ? prev.filter(id => id !== cardId) : [...prev, cardId]);
    if (maximizedCard === cardId) setMaximizedCard(null);
  };

  const toggleMaximizeCard = (cardId: number) => {
    setMaximizedCard(prev => prev === cardId ? null : cardId);
  };

  const restoreCard = (cardId: number) => {
    setMinimizedCards(minimizedCards.filter(id => id !== cardId));
    setMaximizedCard(null);
  };

  const togglePinCard = (cardId: number) => {
    setPinnedCards(prev => prev.includes(cardId) ? prev.filter(id => id !== cardId) : [...prev, cardId]);
  };

  const toggleNotificationsDropdown = () => {
    setShowNotifications(!showNotifications);
  };

  const markAllNotificationsAsRead = () => {
    setNotifications(notifications.map((n: Notification) => ({ ...n, read: true })));
  };

  const OriginalQuickBoardComponent = () => (
    <div className="flex flex-col gap-6">
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-[hsl(var(--card))] rounded-lg shadow">
          <div className="p-4 border-b border-[hsl(var(--border))] flex justify-between items-center">
            <h2 className="font-semibold text-[hsl(var(--card-foreground))]">Quick Links</h2>
            <div className="flex gap-1">
              <button className="p-1 rounded hover:bg-[hsl(var(--accent))] text-[hsl(var(--accent-foreground))]"><Maximize2 size={16} /></button>
              <button className="p-1 rounded hover:bg-[hsl(var(--accent))] text-[hsl(var(--accent-foreground))]"><Minimize2 size={16} /></button>
              <button className="p-1 rounded hover:bg-[hsl(var(--accent))] text-[hsl(var(--accent-foreground))]"><X size={16} /></button>
            </div>
          </div>
          <div className="p-4">
            <div className="flex border-b border-[hsl(var(--border))] mb-4">
              {/* Using chart-3 for orange accent */}
              <button className="px-4 py-2 font-medium border-b-2 border-[hsl(var(--chart-3))] text-[hsl(var(--chart-3))]">Supplier</button>
              <button className="px-4 py-2 text-[hsl(var(--muted-foreground))] hover:text-[hsl(var(--foreground))]">Customer</button>
              <button className="px-4 py-2 text-[hsl(var(--muted-foreground))] hover:text-[hsl(var(--foreground))]">Product</button>
            </div>
            <div className="space-y-4">
              {['Supplier View', 'Customer Portal', 'Product Catalog'].map(item => (
                <div key={item} className="flex justify-between items-center p-2 hover:bg-[hsl(var(--accent))] rounded-md">
                  <div className="flex items-center gap-2">
                    <span className="text-[hsl(var(--muted-foreground))]">⊙</span>
                    <span className="text-[hsl(var(--card-foreground))]">{item}</span>
                  </div>
                  <div className="flex items-center gap-2">
                    <button className="text-[hsl(var(--muted-foreground))] hover:text-[hsl(var(--foreground))]"><PlusCircle size={16} /></button>
                    <button className="text-[hsl(var(--muted-foreground))] hover:text-[hsl(var(--foreground))]"><ChevronRight size={16} /></button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
        <div className="bg-[hsl(var(--card))] rounded-lg shadow">
          <div className="p-4 border-b border-[hsl(var(--border))] flex justify-between items-center">
            <h2 className="font-semibold text-[hsl(var(--card-foreground))]">Summary Stats</h2>
             <div className="flex gap-1">
              <button className="p-1 rounded hover:bg-[hsl(var(--accent))] text-[hsl(var(--accent-foreground))]"><Maximize2 size={16} /></button>
              <button className="p-1 rounded hover:bg-[hsl(var(--accent))] text-[hsl(var(--accent-foreground))]"><Minimize2 size={16} /></button>
              <button className="p-1 rounded hover:bg-[hsl(var(--accent))] text-[hsl(var(--accent-foreground))]"><X size={16} /></button>
            </div>
          </div>
          <div className="p-4 space-y-4">
            <div className="p-4 border border-[hsl(var(--border))] rounded bg-[hsl(var(--muted))]">
              <h3 className="font-medium text-[hsl(var(--muted-foreground))]">Analytics Snapshot</h3>
              <p className="text-sm text-[hsl(var(--muted-foreground))]">Key metrics will be displayed here.</p>
            </div>
            <div className="p-4 border border-[hsl(var(--border))] rounded bg-[hsl(var(--muted))]">
              <h3 className="font-medium text-[hsl(var(--muted-foreground))]">Recent Activity</h3>
              <p className="text-sm text-[hsl(var(--muted-foreground))]">Summary of recent actions.</p>
            </div>
          </div>
        </div>
      </div>
      <div className="bg-[hsl(var(--card))] rounded-lg shadow">
        <div className="p-4 border-b border-[hsl(var(--border))] flex justify-between items-center">
          <h2 className="font-semibold text-[hsl(var(--card-foreground))]">Recent Invoices</h2>
           <div className="flex gap-1">
              <button className="p-1 rounded hover:bg-[hsl(var(--accent))] text-[hsl(var(--accent-foreground))]"><Maximize2 size={16} /></button>
              <button className="p-1 rounded hover:bg-[hsl(var(--accent))] text-[hsl(var(--accent-foreground))]"><Minimize2 size={16} /></button>
              <button className="p-1 rounded hover:bg-[hsl(var(--accent))] text-[hsl(var(--accent-foreground))]"><X size={16} /></button>
            </div>
        </div>
        <div className="p-4">
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead>
                <tr className="border-b border-[hsl(var(--border))]">
                  <th className="text-left p-2 font-medium text-[hsl(var(--muted-foreground))]">Invoice ID</th>
                  <th className="text-left p-2 font-medium text-[hsl(var(--muted-foreground))]">Status</th>
                  <th className="text-left p-2 font-medium text-[hsl(var(--muted-foreground))]">Method</th>
                  <th className="text-right p-2 font-medium text-[hsl(var(--muted-foreground))]">Amount</th>
                </tr>
              </thead>
              <tbody>
                {/* Chart-2 for Green, Chart-3 for Yellow, Destructive for Red */}
                <tr className="border-b border-[hsl(var(--border))] hover:bg-[hsl(var(--accent))]">
                  <td className="p-2 text-[hsl(var(--card-foreground))]">INV001</td>
                  <td className="p-2"><span className="px-2 py-1 bg-[hsla(var(--chart-2),0.1)] text-[hsl(var(--chart-2))] rounded text-xs font-medium">Paid</span></td>
                  <td className="p-2 text-[hsl(var(--card-foreground))]">Credit Card</td>
                  <td className="p-2 text-right text-[hsl(var(--primary))] font-medium">$250.00</td>
                </tr>
                <tr className="border-b border-[hsl(var(--border))] hover:bg-[hsl(var(--accent))]">
                  <td className="p-2 text-[hsl(var(--card-foreground))]">INV002</td>
                  <td className="p-2"><span className="px-2 py-1 bg-[hsla(var(--chart-3),0.1)] text-[hsl(var(--chart-3))] rounded text-xs font-medium">Pending</span></td>
                  <td className="p-2 text-[hsl(var(--card-foreground))]">Direct Transfer</td>
                  <td className="p-2 text-right text-[hsl(var(--primary))] font-medium">$150.00</td>
                </tr>
                <tr className="hover:bg-[hsl(var(--accent))]">
                  <td className="p-2 text-[hsl(var(--card-foreground))]">INV003</td>
                  <td className="p-2"><span className="px-2 py-1 bg-[hsla(var(--destructive),0.1)] text-[hsl(var(--destructive))] rounded text-xs font-medium">Overdue</span></td>
                  <td className="p-2 text-[hsl(var(--card-foreground))]">Paypal</td>
                  <td className="p-2 text-right text-[hsl(var(--primary))] font-medium">$300.00</td>
                </tr>
              </tbody>
            </table>
          </div>
          <div className="mt-4 text-sm text-[hsl(var(--muted-foreground))]">A list of recent financial transactions.</div>
          <div className="mt-4">
            <button className="px-4 py-2 bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))] hover:brightness-95 rounded-md text-sm font-medium">Create New Invoice</button>
          </div>
        </div>
      </div>
    </div>
  );

  return (
    <div className="flex h-screen bg-[hsl(var(--background))] text-[hsl(var(--foreground))]">
      {/* Sidebar */}
      <div className={`bg-[hsl(var(--sidebar-background))] text-[hsl(var(--sidebar-foreground))] flex flex-col ${sidebarExpanded ? 'w-64' : 'w-16'} transition-all duration-300 shadow-lg`}>
        <div className="flex items-center justify-between p-4 border-b border-[hsl(var(--sidebar-border))] h-16">
          {sidebarExpanded && <span className="font-semibold text-lg truncate" title={tenant.name}>{tenant.name} Client</span>}
          <button 
            onClick={toggleSidebar} 
            className="p-1 rounded hover:bg-[hsl(var(--sidebar-hover-background))] text-[hsl(var(--sidebar-foreground))]"
          >
            {sidebarExpanded ? <ChevronLeft size={20} /> : <ChevronRight size={20} />}
          </button>
        </div>
        <nav className="flex-1 overflow-y-auto py-2">
          {navItems.map((item) => (
            <button
              key={item.title}
              title={item.title}
              className={`flex items-center w-full p-3 text-sm transition-colors ${
                activeSection === item.title
                  ? 'bg-[hsl(var(--sidebar-active-background))] text-[hsl(var(--sidebar-foreground))]' // Active item uses sidebar foreground
                  : 'hover:bg-[hsl(var(--sidebar-hover-background))] hover:text-[hsl(var(--sidebar-foreground-hover))]'
              }`}
              onClick={() => setActiveSection(item.title)}
            >
              {item.icon}
              {sidebarExpanded && <span className="ml-3">{item.title}</span>}
            </button>
          ))}
        </nav>
        {minimizedCards.length > 0 && (
          <div className="border-t border-[hsl(var(--sidebar-border))] p-2">
            <div className={`flex ${sidebarExpanded ? 'flex-wrap gap-2' : 'flex-col items-center gap-2'}`}>
              {minimizedCards.map(cardId => {
                const card = mainBoardCards.find(c => c.id === cardId);
                return card ? (
                  <button
                    key={cardId}
                    onClick={() => restoreCard(cardId)}
                    title={`Restore ${card.title}`}
                    // Using a generic dark button style for minimized items, or could use sidebar active style
                    className="bg-[hsl(var(--sidebar-active-background))] text-xs p-2 rounded flex items-center text-[hsl(var(--sidebar-foreground))] hover:brightness-125 w-full sm:w-auto justify-center"
                  >
                    {sidebarExpanded ? card.title : card.title.charAt(0).toUpperCase()}
                  </button>
                ) : null;
              })}
            </div>
          </div>
        )}
      </div>

      {/* Main Content Area */}
      <div className="flex-1 overflow-hidden flex flex-col">
        {/* Header */}
        <header className="bg-[hsl(var(--card))] border-b border-[hsl(var(--border))] flex flex-col shadow-sm">
          <div className="p-4 flex justify-between items-center h-16">
            <h1 className="text-xl font-semibold text-[hsl(var(--card-foreground))]">{activeSection}</h1>
            <div className="flex items-center gap-3 sm:gap-4">
              {/* Notifications */}
              <div className="relative">
                <button
                  className="p-2 rounded-full hover:bg-[hsl(var(--accent))] relative text-[hsl(var(--muted-foreground))] hover:text-[hsl(var(--accent-foreground))]"
                  onClick={toggleNotificationsDropdown}
                  title="Notifications"
                >
                  <Bell size={20} />
                  {notifications.some((n: Notification) => !n.read) && (
                    <span className="absolute top-0 right-0 block h-2.5 w-2.5 rounded-full ring-2 ring-[hsl(var(--card))] bg-[hsl(var(--destructive))]" />
                  )}
                </button>
                {showNotifications && (
                  <div className="absolute right-0 mt-2 w-80 bg-[hsl(var(--popover))] rounded-lg shadow-xl z-20 border border-[hsl(var(--border))]">
                    <div className="p-3 border-b border-[hsl(var(--border))] flex justify-between items-center">
                      <h3 className="font-medium text-sm text-[hsl(var(--popover-foreground))]">Notifications</h3>
                      {notifications.some((n: Notification) => !n.read) && (
                        <button onClick={markAllNotificationsAsRead} className="text-xs text-[hsl(var(--primary))] hover:underline">
                          Mark all as read
                        </button>
                      )}
                    </div>
                    <div className="max-h-80 overflow-y-auto">
                      {notifications.length === 0 ? (
                        <div className="p-4 text-center text-sm text-[hsl(var(--muted-foreground))]">No new notifications</div>
                      ) : (
                        notifications.map((notification: Notification) => (
                          <div
                            key={notification.id}
                            className={`p-3 border-b border-[hsl(var(--border))] text-sm ${notification.read ? 'text-[hsl(var(--muted-foreground))]' : 'bg-[hsla(var(--primary),0.05)] font-medium text-[hsl(var(--popover-foreground))]'}`}
                          >
                            <p>{notification.text}</p>
                          </div>
                        ))
                      )}
                    </div>
                     {notifications.length > 0 && (
                        <div className="p-2 text-center border-t border-[hsl(var(--border))]">
                            <a href="#" className="text-xs text-[hsl(var(--primary))] hover:underline">View all notifications</a>
                        </div>
                    )}
                  </div>
                )}
              </div>
              {/* User Menu Button */}
              <button className="p-1.5 rounded-full hover:bg-[hsl(var(--accent))] text-[hsl(var(--muted-foreground))] hover:text-[hsl(var(--accent-foreground))]" title="User Menu">
                <Menu size={20} />
              </button>
            </div>
          </div>
          {/* Pinned Cards Bar */}
          {pinnedCards.length > 0 && (
            <div className="bg-[hsl(var(--muted))] px-4 py-2 flex gap-3 overflow-x-auto border-b border-[hsl(var(--border))]">
              {pinnedCards.map(cardId => {
                const card = mainBoardCards.find(c => c.id === cardId);
                return card ? (
                  <div key={cardId} className="flex items-center px-3 py-1.5 bg-[hsl(var(--card))] rounded-md shadow-sm border border-[hsl(var(--border))] text-sm">
                    <Pin size={14} className="text-[hsl(var(--primary))] mr-2" />
                    <span className="font-medium text-[hsl(var(--card-foreground))]">{card.title}</span>
                    <button
                      onClick={() => togglePinCard(cardId)}
                      className="ml-2 text-[hsl(var(--muted-foreground))] hover:text-[hsl(var(--destructive))]"
                      title={`Unpin ${card.title}`}
                    >
                      <X size={14} />
                    </button>
                  </div>
                ) : null;
              })}
            </div>
          )}
        </header>

        {/* Main content */}
        <main className="flex-1 p-4 sm:p-6 overflow-auto bg-[hsl(var(--muted))]">
          {activeSection === 'Overview' ? (
            initialDashboardContent
          ) : activeSection === 'Main Board' ? (
            maximizedCard !== null ? (
              <div className="bg-[hsl(var(--card))] rounded-lg shadow-xl p-4 sm:p-6 h-full flex flex-col">
                <div className="flex justify-between items-center mb-4">
                  <h2 className="text-lg font-semibold text-[hsl(var(--card-foreground))]">
                    {mainBoardCards.find(c => c.id === maximizedCard)?.title}
                  </h2>
                  <div className="flex gap-2">
                    <button
                      onClick={() => { if (maximizedCard !== null) togglePinCard(maximizedCard); }}
                      className={`p-1.5 rounded hover:bg-[hsl(var(--accent))] ${maximizedCard !== null && pinnedCards.includes(maximizedCard) ? 'text-[hsl(var(--primary))]' : 'text-[hsl(var(--muted-foreground))]'}`}
                      title={maximizedCard !== null && pinnedCards.includes(maximizedCard) ? "Unpin Card" : "Pin Card"}
                    >
                      <Pin size={18} />
                    </button>
                    <button
                      onClick={() => { if (maximizedCard !== null) toggleMinimizeCard(maximizedCard); }}
                      className="p-1.5 rounded hover:bg-[hsl(var(--accent))] text-[hsl(var(--muted-foreground))]"
                      title="Minimize Card"
                    >
                      <Minimize2 size={18} />
                    </button>
                    <button
                      onClick={() => setMaximizedCard(null)}
                      className="p-1.5 rounded hover:bg-[hsl(var(--accent))] text-[hsl(var(--muted-foreground))]"
                      title="Restore Down"
                    >
                      <X size={18} />
                    </button>
                  </div>
                </div>
                <div className="flex-1 bg-[hsl(var(--muted))] rounded p-4 flex items-center justify-center text-[hsl(var(--muted-foreground))]">
                  Maximized Content for {mainBoardCards.find(c => c.id === maximizedCard)?.title} would go here.
                </div>
              </div>
            ) : (
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                {mainBoardCards.filter(card => !minimizedCards.includes(card.id)).map(card => (
                  <div
                    key={card.id}
                    className={`bg-[hsla(var(${card.themeColorVar}),0.15)] rounded-lg shadow-md p-4 min-h-[160px] flex flex-col transition-shadow hover:shadow-lg`}
                  >
                    <div className="flex justify-between items-start mb-2">
                      <h3 className={`font-semibold text-[hsl(var(${card.themeColorVar}))]`}>{card.title}</h3>
                      <div className="flex gap-1">
                        <button onClick={() => togglePinCard(card.id)} className={`p-1 rounded hover:bg-[hsla(var(${card.themeColorVar}),0.3)] ${pinnedCards.includes(card.id) ? `text-[hsl(var(${card.themeColorVar}))]` : 'text-[hsl(var(--muted-foreground))]'}`} title={pinnedCards.includes(card.id) ? "Unpin" : "Pin"}> <Pin size={16} /> </button>
                        <button onClick={() => toggleMinimizeCard(card.id)} className={`p-1 rounded hover:bg-[hsla(var(${card.themeColorVar}),0.3)] text-[hsl(var(--muted-foreground))]`} title="Minimize"> <Minimize2 size={16} /> </button>
                        <button onClick={() => toggleMaximizeCard(card.id)} className={`p-1 rounded hover:bg-[hsla(var(${card.themeColorVar}),0.3)] text-[hsl(var(--muted-foreground))]`} title="Maximize"> <Maximize2 size={16} /> </button>
                        <button onClick={() => setShowModal(true)} className={`p-1 rounded hover:bg-[hsla(var(${card.themeColorVar}),0.3)] text-[hsl(var(--muted-foreground))]`} title="More Options"> <Layers size={16} /> </button>
                      </div>
                    </div>
                    <div className="flex-1 flex items-center justify-center text-sm text-[hsl(var(--muted-foreground))]">
                      Content for {card.title}
                    </div>
                  </div>
                ))}
                <button
                  onClick={() => console.log("Add new card to Main Board")}
                  className="bg-[hsl(var(--card))] border-2 border-dashed border-[hsl(var(--border))] rounded-lg shadow-sm p-4 min-h-[160px] flex flex-col items-center justify-center text-[hsl(var(--muted-foreground))] hover:border-[hsl(var(--primary))] hover:text-[hsl(var(--primary))] transition-colors group"
                >
                  <PlusCircle size={32} className="mb-2 group-hover:scale-110 transition-transform" />
                  <span className="font-medium">Add Widget</span>
                </button>
              </div>
            )
          ) : activeSection === 'My Account' ? (
            <div className="bg-[hsl(var(--card))] p-6 rounded-lg shadow">
              <h2 className="text-xl font-semibold mb-4 text-[hsl(var(--card-foreground))]">My Account Details</h2>
              <p className="text-[hsl(var(--card-foreground))]"><span className="font-medium">Tenant ID:</span> {tenant.id}</p>
              <p className="text-[hsl(var(--card-foreground))]"><span className="font-medium">Tenant Name:</span> {tenant.name}</p>
              <p className="mt-2 text-[hsl(var(--card-foreground))]">Information specific to the logged-in client user will appear here.</p>
            </div>
          ) : activeSection === 'Settings' ? (
             <div className="bg-[hsl(var(--card))] p-6 rounded-lg shadow">
              <h2 className="text-xl font-semibold mb-4 text-[hsl(var(--card-foreground))]">Client Settings</h2>
              <p className="mb-6 text-sm text-[hsl(var(--muted-foreground))]">Manage your notification settings, display options, and other account preferences for this client dashboard.</p>
              <div className="space-y-4">
                <div className="flex items-center justify-between p-3 border border-[hsl(var(--border))] rounded-md">
                  <span className="text-[hsl(var(--card-foreground))]">Enable Detailed System Logs</span>
                  <label className="switch">
                    <input type="checkbox" defaultChecked /> <span className="slider round"></span>
                  </label>
                </div>
                <div className="flex items-center justify-between p-3 border border-[hsl(var(--border))] rounded-md">
                  <span className="text-[hsl(var(--card-foreground))]">Receive Weekly Summary Emails</span>
                   <label className="switch">
                    <input type="checkbox" /> <span className="slider round"></span>
                  </label>
                </div>
                <div className="flex items-center justify-between p-3 border border-[hsl(var(--border))] rounded-md">
                  <span className="text-[hsl(var(--card-foreground))]">Dark Mode (Client View)</span>
                   <label className="switch">
                    <input type="checkbox" /> <span className="slider round"></span>
                  </label>
                </div>
              </div>
            </div>
          ) : activeSection === 'Quick Board (Original)' ? (
            <OriginalQuickBoardComponent />
          ) : (
            <div className="flex items-center justify-center h-full text-lg text-[hsl(var(--muted-foreground))]">
              Select a section from the sidebar.
            </div>
          )}
        </main>
      </div>

      {/* Modal */}
      {showModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4"> {/* Using bg-black/50 from Tailwind for overlay */}
          <div className="bg-[hsl(var(--card))] w-full max-w-2xl rounded-lg shadow-xl">
            <div className="flex justify-between items-center p-4 sm:p-6 border-b border-[hsl(var(--border))]">
              <h2 className="text-xl font-semibold text-[hsl(var(--card-foreground))]">Card Options / Details</h2>
              <button onClick={() => setShowModal(false)} className="p-1.5 rounded-full hover:bg-[hsl(var(--accent))] text-[hsl(var(--muted-foreground))]"> <X size={20} /> </button>
            </div>
            <div className="p-4 sm:p-6 min-h-[200px] max-h-[60vh] overflow-y-auto text-[hsl(var(--card-foreground))]">
              <p>This is a generic modal. Content for the currently active card or action would go here.</p>
              <p>For example, if triggered from a main board card, it might show more details or actions for that item.</p>
            </div>
            <div className="p-4 sm:p-6 border-t border-[hsl(var(--border))] flex justify-end gap-3">
              <button 
                onClick={() => setShowModal(false)} 
                className="px-4 py-2 text-sm font-medium text-[hsl(var(--secondary-foreground))] bg-[hsl(var(--secondary))] hover:brightness-95 rounded-md"
              >
                Close
              </button>
              <button 
                onClick={() => { console.log("Modal action confirmed"); setShowModal(false); }} 
                className="px-4 py-2 text-sm font-medium text-[hsl(var(--primary-foreground))] bg-[hsl(var(--primary))] hover:brightness-95 rounded-md"
              >
                Confirm Action
              </button>
            </div>
          </div>
        </div>
      )}
      
      {/* Global styles for toggle switch using CSS variables */}
      <style jsx global>{`
        .switch { position: relative; display: inline-block; width: 34px; height: 20px; }
        .switch input { opacity: 0; width: 0; height: 0; }
        .slider { 
          position: absolute; 
          cursor: pointer; 
          top: 0; left: 0; right: 0; bottom: 0; 
          background-color: hsl(var(--muted)); 
          transition: .4s; 
        }
        .slider:before { 
          position: absolute; 
          content: ""; 
          height: 12px; width: 12px; 
          left: 4px; bottom: 4px; 
          background-color: hsl(var(--background)); /* Knob color, white for light bg, could be themed for dark */
          transition: .4s; 
        }
        input:checked + .slider { background-color: hsl(var(--primary)); }
        input:checked + .slider:before { transform: translateX(14px); }
        .slider.round { border-radius: 20px; }
        .slider.round:before { border-radius: 50%; }

        /* Ensure knob is visible in dark mode if --background becomes dark */
        [data-theme="dark"] .slider:before {
           background-color: hsl(var(--card-foreground)); /* A light color for dark theme knob */
        }
        @media (prefers-color-scheme: dark) {
          :not([data-theme="light"]) .slider:before {
            background-color: hsl(var(--card-foreground)); /* A light color for dark theme knob */
          }
        }
      `}</style>
    </div>
  );
}